use super::*;
#[test]
fn original_window_catalog_sources_and_tickets_match_physical_original_grants(){
 type O=crate::camera_owner::RetainedLoadOwnerA;let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let row=law["grant"].as_array().unwrap();let grant=RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize};
 for axis in [0,1,2,4]{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,_=>denied.maximum_depth=0}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||bounded_window_config_store_owners::<O>(denied));assert!(result.is_err());let error=result.err().unwrap();assert!(error.owners.is_none());assert_eq!(error.progress,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let((mut owners,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||bounded_window_config_store_owners::<O>(grant).map_err(|error|error.error).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(owners.original_semantic_issuer_is_shared());assert!(!owners.constructor_is_complete());let mut allocated=p.retained_capacity_bytes;let mut released=0;while !owners.constructor_is_complete(){let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owners.admit_constructor(grant).map_err(|(error,_)|error).unwrap());assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));allocated+=p.retained_capacity_bytes;released+=p.released_bytes;}
 while !owners.uninstalled_owners_terminal_is_empty(){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owners.close_uninstalled_owners_step(grant).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));allocated+=p.retained_capacity_bytes;released+=p.released_bytes;assert_ne!(p,Default::default());}assert_eq!(allocated,released);
}